import type { KnobId, MeasuredId, Subject } from '../../types/domain';

/*
 * 규칙 해석 말뭉치(ADR-013·026). "어떻게 입력하든 알아서"를 재는 기준이라 기대값을 결과에 맞춰 고치지 않는다.
 * 이름은 모두 가상이다(김타자·박투수·가나원·도레미·나다른). 실존 선수 이름을 쓰지 않는다.
 * 팀은 원정 KIA·홈 롯데. 'home'·'away'는 맥락(누가 공격 중인지)에 따라 battingTeam·fieldingTeam으로 바꿔 본다.
 */

export type CorpusGroup =
  | 'app' | 'name' | 'team' | 'env' | 'daily' | 'command' | 'negation'
  | 'slang' | 'multi' | 'unknown' | 'sensitive' | 'boundary';

export type ExpectedSubject = Subject | 'home' | 'away';

export interface Expectation {
  /** 허용 대상(하나라도 맞으면 된다) */
  subjects?: readonly ExpectedSubject[];
  /** 허용 손잡이 */
  knobs?: readonly KnobId[];
  /** 그 손잡이 세기의 부호 */
  sign?: 1 | -1;
}

export interface CorpusCase extends Expectation {
  text: string;
  group: CorpusGroup;
  /** 민감 입력이면 true */
  refused?: boolean;
  /** 실측 변수를 쓸 수 있을 때 함께 나와야 할 변수 */
  measured?: MeasuredId;
  /** 여러 TMI 문장: 각 기대가 서로 다른 효과로 모두 맞아야 한다 */
  all?: readonly Expectation[];
}

